"""Command line interface: ``pennywise balance|summary|list|add|export``."""

import argparse
import csv
import io
import json
import os
import sys

from . import ledger

_VALUE_OPTIONS = ("--category", "--since", "--until", "--by", "--format")


class _Parser(argparse.ArgumentParser):
    def error(self, message):
        self.print_usage(sys.stderr)
        self.exit(2, "%s: error: %s\n" % (self.prog, message))


def _date_arg(text):
    try:
        return ledger.parse_date(text)
    except ledger.ParseError:
        raise argparse.ArgumentTypeError(
            "invalid date %r (expected a real YYYY-MM-DD date)" % text
        ) from None


def _build_parser():
    parser = _Parser(prog="pennywise", description="Report on a plain-text ledger.",
                     allow_abbrev=False)
    sub = parser.add_subparsers(dest="command", required=True, metavar="COMMAND",
                                parser_class=_Parser)

    def command(name, help_text, file_help="ledger file, or - for standard input"):
        p = sub.add_parser(name, help=help_text, description=help_text, allow_abbrev=False)
        p.add_argument("file", metavar="FILE", help=file_help)
        return p

    p = command("balance", "print the total of all amounts")
    p.add_argument("--json", action="store_true", help="print JSON")

    p = command("summary", "print totals per category or month")
    p.add_argument("--by", choices=("category", "month"), default="category")
    p.add_argument("--json", action="store_true", help="print JSON")

    p = command("list", "print entries, oldest first")
    p.add_argument("--category", help="only this category (any case)")
    p.add_argument("--since", type=_date_arg, metavar="DATE", help="from DATE, inclusive")
    p.add_argument("--until", type=_date_arg, metavar="DATE", help="up to DATE, inclusive")
    p.add_argument("--json", action="store_true", help="print JSON")

    p = command("export", "print entries as CSV, in list order")
    p.add_argument("--format", choices=("csv",), default="csv")

    p = command("add", "append an entry to the file", file_help="ledger file (not -)")
    p.add_argument("date", metavar="DATE")
    p.add_argument("category", metavar="CATEGORY")
    p.add_argument("amount", metavar="AMOUNT")
    p.add_argument("note", metavar="NOTE", nargs="?", default="")
    return parser


def _prepare(argv):
    """Make values that start with a dash read as values, not as options."""
    out, i = [], 0
    if argv and argv[0] == "add" and not (len(argv) > 1 and argv[1] in ("-h", "--help")):
        return [argv[0], "--"] + argv[1:]
    while i < len(argv):
        tok = argv[i]
        if tok == "--":
            out.extend(argv[i:])
            break
        if tok in _VALUE_OPTIONS and i + 1 < len(argv):
            out.append(tok + "=" + argv[i + 1])
            i += 2
            continue
        out.append(tok)
        i += 1
    return out


class _Fail(Exception):
    def __init__(self, code, message):
        super().__init__(message)
        self.code = code


def _read(file):
    try:
        if file == "-":
            stream = sys.stdin
            raw = stream.buffer.read() if hasattr(stream, "buffer") else stream.read()
        else:
            with open(file, "rb") as f:
                raw = f.read()
        text = raw.decode("utf-8-sig") if isinstance(raw, bytes) else raw
    except (OSError, UnicodeDecodeError, ValueError) as exc:
        reason = exc.strerror if isinstance(exc, OSError) and exc.strerror else exc
        raise _Fail(2, "pennywise: %s: cannot read: %s" % (file, reason)) from None
    try:
        return ledger.parse(text)
    except ledger.ParseError as exc:
        raise _Fail(1, "pennywise: %s: %s" % (file, exc)) from None


def _json(obj):
    return json.dumps(obj)


def _csv(entries):
    buf = io.StringIO()
    w = csv.writer(buf, lineterminator="\n")
    w.writerow(("date", "category", "amount", "note"))
    for e in entries:
        w.writerow((e.date.isoformat(), e.category, ledger.format_amount(e.amount), e.note))
    return buf.getvalue()


def _sorted(entries):
    return sorted(entries, key=lambda e: e.date)


def _lines(lines):
    return "".join(line + "\n" for line in lines)


def _run_read(args):
    entries = _read(args.file)
    fmt = ledger.format_amount
    if args.command == "balance":
        total = fmt(ledger.balance(entries))
        return _json({"balance": total}) + "\n" if args.json else total + "\n"
    if args.command == "summary":
        group = ledger.by_category if args.by == "category" else ledger.by_month
        totals = {k: fmt(v) for k, v in sorted(group(entries).items())}
        if args.json:
            return _json(totals) + "\n"
        return _lines("%s  %s" % kv for kv in totals.items())
    shown = _sorted(entries)
    if args.command == "list":
        shown = _sorted(ledger.filter_entries(entries, args.category, args.since, args.until))
        if args.json:
            return _json([
                {"date": e.date.isoformat(), "category": e.category,
                 "amount": fmt(e.amount), "note": e.note} for e in shown
            ]) + "\n"
        return _lines(ledger.format_entry(e) for e in shown)
    return _csv(shown)


def _run_add(args):
    if args.file == "-":
        raise _Fail(2, "pennywise: add: FILE cannot be - (standard input)")
    try:
        entry = ledger.make_entry(args.date, args.category, args.amount, args.note)
    except ledger.ParseError as exc:
        raise _Fail(1, "pennywise: invalid entry: %s" % exc) from None
    line = ledger.format_entry(entry)
    try:
        with open(args.file, "a+b") as f:
            prefix = b""
            if f.seek(0, os.SEEK_END) > 0:
                f.seek(-1, os.SEEK_END)
                if f.read(1) != b"\n":
                    prefix = b"\n"
            f.write(prefix + line.encode("utf-8") + b"\n")
    except OSError as exc:
        raise _Fail(2, "pennywise: %s: cannot write: %s" % (args.file, exc.strerror or exc)) from None
    return line + "\n"


def _emit(text):
    """Write ``text`` to stdout; return an exit status for a failed write."""
    try:
        sys.stdout.write(text)
        sys.stdout.flush()
        return 0
    except BrokenPipeError:
        status = 0
    except OSError as exc:
        print("pennywise: cannot write output: %s" % (exc.strerror or exc), file=sys.stderr)
        status = 2
    try:  # keep the interpreter's exit-time flush from failing again
        os.dup2(os.open(os.devnull, os.O_WRONLY), sys.stdout.fileno())
    except (OSError, ValueError, AttributeError, io.UnsupportedOperation):
        pass
    return status


def main(argv=None):
    argv = list(sys.argv[1:] if argv is None else argv)
    parser = _build_parser()
    try:
        args = parser.parse_args(_prepare(argv))
    except SystemExit as exc:
        return exc.code if isinstance(exc.code, int) else 2
    try:
        out = _run_add(args) if args.command == "add" else _run_read(args)
    except _Fail as exc:
        print(exc, file=sys.stderr)
        return exc.code
    return _emit(out)
