import datetime
import decimal
import re
from dataclasses import dataclass
from decimal import Decimal

# Exact arithmetic: the default context rounds at 28 digits.
_CTX = decimal.Context(
    prec=decimal.MAX_PREC,
    Emax=decimal.MAX_EMAX,
    Emin=decimal.MIN_EMIN,
    traps=[decimal.InvalidOperation, decimal.DivisionByZero, decimal.Overflow],
)
_CENT = Decimal("0.01")
_DATE_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")
_AMOUNT_RE = re.compile(r"[+-]?[0-9]+(\.[0-9]{1,2})?")
_SEP_RE = re.compile(r"[ \t]+")


class ParseError(ValueError):
    """A line of the ledger is not valid. ``line`` is its 1-based number."""

    def __init__(self, line, reason):
        self.line = line
        self.reason = reason
        super().__init__("line %d: %s" % (line, reason))


@dataclass(frozen=True)
class Entry:
    date: datetime.date
    category: str
    amount: Decimal
    note: str = ""


def parse_date(text, line=1):
    if not _DATE_RE.fullmatch(text):
        raise ParseError(line, "invalid date %r (expected YYYY-MM-DD)" % text)
    try:
        return datetime.date(int(text[:4]), int(text[5:7]), int(text[8:]))
    except ValueError:
        raise ParseError(line, "invalid date %r (no such day)" % text) from None


def parse_amount(text, line=1):
    if not _AMOUNT_RE.fullmatch(text):
        raise ParseError(
            line, "invalid amount %r (up to two decimals, e.g. -12.50)" % text
        )
    return Decimal(text)


def make_entry(date, category, amount, note="", line=1):
    """Validate the four fields of an entry and build it."""
    if not category or _SEP_RE.search(category) or category != category.strip():
        raise ParseError(line, "invalid category %r (one word)" % category)
    if "\n" in note or "\r" in note:
        raise ParseError(line, "note must be a single line")
    return Entry(
        parse_date(date, line),
        category.lower(),
        parse_amount(amount, line),
        note.strip(),
    )


def parse(text):
    """Parse ledger text into a list of Entry, in file order."""
    if text.startswith("﻿"):
        text = text[1:]
    entries = []
    for number, raw in enumerate(text.split("\n"), 1):
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        fields = _SEP_RE.split(line, maxsplit=3)
        if len(fields) < 3:
            raise ParseError(
                number, "expected DATE CATEGORY AMOUNT [NOTE], got %r" % line
            )
        entries.append(make_entry(*fields, line=number))
    return entries


def _total(amounts):
    total = Decimal(0)
    for amount in amounts:
        total = _CTX.add(total, amount)
    return total


def balance(entries):
    """Total of all amounts (Decimal zero for no entries)."""
    return _total(e.amount for e in entries)


def _group(entries, key):
    groups = {}
    for e in entries:
        groups.setdefault(key(e), []).append(e.amount)
    return {k: _total(v) for k, v in groups.items()}


def by_category(entries):
    return _group(entries, lambda e: e.category)


def month_key(date):
    return "%04d-%02d" % (date.year, date.month)


def by_month(entries):
    return _group(entries, lambda e: month_key(e.date))


def filter_entries(entries, category=None, since=None, until=None):
    """Entries matching all given filters, in the order given."""
    wanted = category.lower() if category is not None else None
    return [
        e
        for e in entries
        if (wanted is None or e.category.lower() == wanted)
        and (since is None or e.date >= since)
        and (until is None or e.date <= until)
    ]


def format_amount(amount):
    """Amount with exactly two decimals; zero is never negative."""
    q = _CTX.quantize(Decimal(amount), _CENT)
    if q.is_zero():
        q = abs(q)
    return str(q)


def format_entry(entry):
    """``DATE CATEGORY AMOUNT[ NOTE]`` — the line written by ``list`` and ``add``."""
    line = "%s %s %s" % (entry.date.isoformat(), entry.category, format_amount(entry.amount))
    return line + " " + entry.note if entry.note else line
